internal final class NDXKCS_KBVRequestTableTransferProcess extends NDXTransferToD365 implements NDXTransferToD365Interface
{
}

Method.Source:
private void writeKCS_KBVRequestTable(Niedax.AX.TableRecordModels.TableRecord _record)
{
    System.Exception ex;

    Niedax.AX.TableRecordModels.KCS_KBVRequestTable kcs_KBVRequestTable = _record;
    KCS_KBVRequestTable lKCS_KBVRequestTable;
    KCS_KBVRequestId requestId = '';

    str message = strFmt("KCS_KBVRequestTable %1 entered on %2", kcs_KBVRequestTable.ToString(), this.environment);

    try
    {
        requestId =  kcs_KBVRequestTable.KCS_KBVRequestId;
        if(_record.IsAX2009 && kcs_KBVRequestTable.KCS_KBVRequestId.Length < 9)
        {
            for(int i = 0; i< 9 - kcs_KBVRequestTable.KCS_KBVRequestId.Length; i++)
            {
                requestId = strIns(requestId, '0',0);
            }
        }

        changecompany(kcs_KBVRequestTable.DataAreaId)
        {
            lKCS_KBVRequestTable = KCS_KBVRequestTable::find(requestId);
        }

        //Make only updates on an existing record, since the records are created by determination process in d365
        if(!lKCS_KBVRequestTable)
        {
            message = strFmt("Record %1 does not exist on %2",  kcs_KBVRequestTable.ToString(), this.environment);
            throw Error(message);
        }
        else
        {
            message = strFmt("KCS_KBVRequestTable %1 inserted or found on %2", lKCS_KBVRequestTable.KCS_KBVRequestID, this.environment);
            response.RecId = lKCS_KBVRequestTable.RecId;
            response.Success = true;
        }    

    }
    catch(ex)
    {
        message = message + "-" + ex.Message;
    }

    response.Message = message;
}

/// <summary>
/// Updates or creates corresponding record
/// </summary>
/// <param name = "_record">record instance</param>
/// <returns>Response</returns>
public Niedax.D365.API.Models.D365_APIResponse writeRecord(Niedax.AX.TableRecordModels.TableRecord _record)
{
    this.writeKCS_KBVRequestTable(_record);
    return response;
}
